function buildMoves(char){const out={};for(const k in BASE_MOVES){const md=char.mods&&char.mods[k];out[k]={...BASE_MOVES[k],...(typeof md==='function'?md(BASE_MOVES[k]):(md||{}))}}return out}
// Für die Move-Liste im UI (Allgemeines). Figurenspezifische Moves: charMoves(char)
const MOVE_LIST=[
 ['Light / Medium / Heavy','J / K / L','Chain: L → M → H, danach Special-Cancel'],
 ['Command-Normals','→ + K  /  → + L','Je Figur anders (Überkopf, Griff, Vorstoß …)'],
 ['Special-Taste','U  (neutral / → / ↓ / ←)','Specials ohne Motion: neutral, vorwärts, unten, zurück'],
 ['Luft-Special','U in der Luft','Je Figur anders (Sturz, Projektil …)'],
 ['Stärke der Specials','Motion + J / K / L','Leicht = schnell & schwach, Heavy = langsam & stark (Wellen/Bälle)'],
 ['Hyper','I (1 Balken)','Je Figur anders'],
 ['Dash / Air-Dash','O  oder  Doppeltipp ←/→','Auch in der Luft (1×)'],
 ['Doppelsprung','W/Space in der Luft','1× pro Luftphase']];
const ORDER_KEYS=['5L','5M','5H','2L','2M','2H','6M','6H','fireball','rising','rush','back','airsp','super'];
function charMoves(char){const mv=buildMoves(char);return ORDER_KEYS.filter(k=>mv[k]).map(k=>[mv[k].label,mv[k].key,mv[k].info||''])}

// ===== core/movesets =====
// Figurenspezifische Movesets. Jede Figur überschreibt die Basis-Moves aus moves.js (nur die Felder, die sich ändern).
// Normals: norm({su,rc,dmg,reach}) = Startup/Recovery-Offset, Schadensfaktor, Reichweiten-Offset für alle Normals.
// Specials: eigene Werte + `info` (Kurztext im Menü) + optional v:{L,M,H} (Variante je nach Taste; Special-Taste U zählt als M).
const NORMALS=['5L','5M','5H','2L','2M','2H','jL','jM','jH'];
const norm=({su=0,rc=0,dmg=1,reach=0})=>{const o={};
 for(const k of NORMALS)o[k]=m=>({su:Math.max(2,m.su+su),rc:Math.max(3,m.rc+rc),dmg:Math.round(m.dmg*dmg),box:[m.box[0],m.box[1],Math.max(40,m.box[2]+reach),m.box[3]]});
 return o};
